333	     i stället för stor text eller en jättesiffra - en tunn linje, ett streck
334	     per steg (aria-hidden) och en mintmarkör som glider kontinuerligt med
335	     pinnens progress, aldrig i steg.
336	     R4 §2: linjen/strecken/markören var nästan osynliga (mätt: 1px linje på
337	     30%, 7px streck) - grövre av alla tre. Etiketten (03) är den flyttade
338	     räknaren (se HTML: samma <span class="showcase-counter">, samma
339	     ingen-ny-copy), inte en andra kopia - box-head ovanför behåller bara
340	     spåret. */
341	  .showcase-scale{position:relative;padding:0 var(--cellpad);min-height:120px;display:flex;flex-direction:column;}
342	  .showcase-scale > .showcase-counter{margin-bottom:10px;flex:none;}
343	  .showcase-scale-track{position:relative;flex:1 1 auto;min-height:100px;}
344	  .showcase-scale-line{position:absolute;top:0;bottom:0;left:1px;width:2px;background:currentColor;opacity:.35;}
345	  .showcase-scale-tick{position:absolute;left:-5px;width:14px;height:1px;background:currentColor;opacity:.25;}
346	  .showcase-scale-tick.is-current{opacity:1;width:20px;left:-8px;}
347	  /* R3 review-animations pass: driven from --marker-y (px, written once per
348	     scroll frame) instead of `top`, so the continuous write is a transform
349	     (GPU-composited) rather than a layout property. */
350	  .showcase-scale-marker{position:absolute;left:0;top:0;width:4px;height:28px;border-radius:2px;background:var(--mint);transform:translateY(calc(var(--marker-y,0px) - 50%));}
351	  .showcase-steps{display:grid;}
352	  /* R3 §4 (F-019): rubriken får aldrig ta över - sajten är huvudsaken,
353	     rutan är bildtexten. h3 tillbaka i rubrikskala (30px), inte
354	     headline-40-tokenet R2 lånade; jättesiffran är borttagen. */
355	  .showcase-row{grid-area:1/1;padding:0 var(--cellpad) calc(var(--cellpad)*1.4);}
356	  .showcase-row h3{font-size:30px;line-height:1.15;font-weight:500;}
357	  .showcase-row p{font-size:18px;line-height:1.5;max-width:40ch;}
358	}
359	@media (max-width:767px){
360	  /* R7 runda 2, fynd 2: .showcase-embed-cell (position:sticky) satt över
361	     .showcase-side (head + rader) i normalt dokumentflöde, så när huvudet
362	     ("Hōrai") rullade upp genom den redan-klistrade ramen (z-index:2) klipptes
363	     det mot ramens underkant (lead: through-02/03). Huvudet ska stå helt
364	     synligt INNAN raderna - och innan ramen - börjar klistra, så .showcase-side
365	     görs display:contents här (bara mobil) för att lyfta .showcase-head och
366	     .showcase-rows till .showcase-stage's egna grid-items, och ordnas om med
367	     `order`: huvud (1) -> ram (2, där klistringen börjar) -> rader (3). */
368	  .showcase-side{display:contents;}
369	  .showcase-head{order:1;}
370	  .showcase-embed-cell{order:2;}
371	  .showcase-rows{display:flex;flex-direction:column;gap:1px;background:#000;order:3;}
372	  .showcase-box-head{display:none;}
373	  .showcase-steps{display:contents;}
374	  .showcase-panel--calyx .showcase-row:nth-child(odd){background:var(--paper);}
375	  .showcase-panel--calyx .showcase-row:nth-child(even){background:var(--grey);}
376	  .showcase-panel--horai .showcase-row:nth-child(odd){background:var(--black);color:var(--paper);}
377	  .showcase-panel--horai .showcase-row:nth-child(odd) p{color:#bdbdbd;}
378	  .showcase-panel--horai .showcase-row:nth-child(even){background:var(--grey);}
379	}
