51	|-----------|------------|--------|-------------|----------------|---------|
52	| 28px | 1.75rem | 500 | 33px | -1px | h1 |
53	| 22px | 1.375rem | 500 | 27px | -1px | h3, h1, h2 |
54	| 20px | 1.25rem | 400 | 35px | normal | span |
55	| 16px | 1rem | 300 | 20.8px | normal | html, body, input, li |
