#!/usr/bin/env python3
"""Measure the new showcase box-head / text / detail cells at 1440x900,
check console errors, and step through Calyx/Horai steps to find the
tallest text-cell height (should be constant) and the detail cell's box."""
import json
import sys
from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:3307/tests/alunix-r8/runs/V3g/index.html"

def main():
    errors = []
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        try:
            page = browser.new_page(viewport={"width": 1440, "height": 900}, device_scale_factor=1)
            page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
            page.on("pageerror", lambda e: errors.append(str(e)))
            page.goto(URL, wait_until="load")
            page.wait_for_timeout(500)

            # scroll into showcase pin and let it settle at progress 0
            page.evaluate("document.getElementById('showcase').scrollIntoView({behavior:'instant', block:'start'})")
            page.wait_for_timeout(300)

            def measure(case_key, n):
                out = []
                for k in range(n):
                    p_val = (k + 0.5) / n
                    page.evaluate(f"""() => {{
                        const CASES = window.__CASES;
                        const C = CASES['{case_key}'];
                        window.__showcaseST_progress_set = {p_val};
                    }}""")
                    # drive the pin via lenis using computed scrollY isn't trivial here;
                    # instead directly call updateShowcase-equivalent through the ST instance.
                    page.evaluate(f"""() => {{
                        const st = window.__CASES && null;
                    }}""")
                    out.append(None)
                return out

            # Simpler: read ScrollTrigger instance progress control via window hook if any.
            has_st = page.evaluate("() => typeof ScrollTrigger !== 'undefined'")
            print("ScrollTrigger available:", has_st)

            box_head = page.query_selector('#showcase-calyx .showcase-box-head')
            steps_cell = page.query_selector('#showcase-calyx .showcase-steps')
            detail_cell = page.query_selector('#showcase-calyx .showcase-detail')
            for name, el in [('box-head', box_head), ('steps', steps_cell), ('detail', detail_cell)]:
                if el:
                    r = el.bounding_box()
                    print(name, r)
                else:
                    print(name, 'NOT FOUND')

            print("console/page errors:", errors)
        finally:
            browser.close()

if __name__ == "__main__":
    main()

