   helt - anropa `<img>.decode()` direkt på Hōrais egna bildelement
   (samma ursprung, `contentDocument` nåbart), den dokumenterade
   webbläsar-API:n för att tvinga fram och cacha avkodningen oavsett
   målningsstatus. visibility stannar 'visible' (mätt: measureCase
   behöver layout, inte målning - se separat fynd), opacity 0 tills
   klick. */
function prewarmInactiveCase(C){
  C.iframe.style.visibility = 'visible';
  var d = null, w = null;
  try { d = C.iframe.contentDocument; w = C.iframe.contentWindow; } catch (e) { d = null; }
  if (!d || !w) return;
  /* Hōrai (och katalogsajterna generellt) sätter sina foton som CSS
     background-image, inte <img> - `<img>.decode()` hittade noll element
     (mätt: d.images.length === 0), vilket är varför den vägen inte
     hjälpte. Bygg tysta Image()-objekt för varje unik background-image-
     URL i dokumentet i stället - webbläsarens avkodade bildcache delas
     per URL oavsett hur den refereras (<img> eller background-image). */
  var seen = {};
  function prewarmUrl(bg){
    var m = bg && /url\(["']?([^"')]+)["']?\)/.exec(bg);
    var url = m && m[1];
    if (url && !seen[url] && url.indexOf('data:') !== 0){
      seen[url] = true;
      var img = new Image();
      img.src = url;
      if (img.decode) img.decode().catch(function(){});
    }
  }
  /* R5 bugfix: bara elementens EGEN computed style missade en
     bakgrundsbild som satt enbart på ett ::before-pseudoelement (mätt:
     1 av 6 bakgrundsbilder i Hōrai) - ::before/::after läses inte via
     querySelectorAll, så de måste hämtas explicit. */
  Array.prototype.slice.call(d.querySelectorAll('*')).forEach(function(el){
    prewarmUrl(w.getComputedStyle(el).backgroundImage);
    prewarmUrl(w.getComputedStyle(el, '::before').backgroundImage);
    prewarmUrl(w.getComputedStyle(el, '::after').backgroundImage);
  });
  /* R6 runda 6: samma förvärmning för den här casens EGNA stegbilder i den
     nya detaljcellen (färg + dither, båda vanliga <img>, inte background-
     image) - Hōrai-panelen är display:none tills klick, och samma R5-fynd
     gäller oavsett hur bilden refereras: avkodningen skjuts upp tills
     webbläsaren tror elementet är viktigt, aldrig av CSS-tillstånd allena.
     Fristående Image()-objekt igen, aldrig activateCase. */
  if (C.figures && C.figures.length){
    C.figures.forEach(function(fig){
      Array.prototype.slice.call(fig.querySelectorAll('img')).forEach(function(img){
        prewarmUrl('url(' + img.getAttribute('src') + ')');
      });
    });
  }
}

Object.keys(CASES).forEach(function(key){
  var C = CASES[key];
  if (!C.iframe) return;
  C.iframe.addEventListener('load', function(){
    measureCaseSettled(C);
    C.loaded = true;
    if (activeCaseKey === C.key){
      /* A#3: once loaded, the iframe fades in over 0.3s from behind its
         poster (SHOWCASE-SPEC §A) - the same duration whether this is the
         first real load or a later reload. */
      gsap.to(C.iframe, {
        opacity: 1, duration: 0.3, ease: 'power2.out', overwrite: 'auto',
        onComplete: function(){ if (C.poster) C.poster.style.display = 'none'; }
      });
      if (window.innerWidth >= 768){
        if (showcaseST) updateShowcase(C, showcaseST.progress);
      } else {
        tweenCaseTo(C, C.pendingRow || 0);
      }
    } else {
      prewarmInactiveCase(C);
    }
  });
});

